function authStatus(message,error=false){const el=document.getElementById('authStatus');if(el){el.textContent=message;el.style.color=error?'var(--danger)':'var(--muted)'}}
const ADMIN_EMAIL='admin@aahanapestcontrol.in';
let sessionStarting=false,recoveryMode=false,sessionEpoch=0;
function resetWorkspace(){historicalBills=[];erpRecords=[];syncedBaselines={};cloudDirty=false;cloudReady=false;cloudHydrating=false;cloudUser=null;cloudOrgId=null;sessionEpoch++;clearTimeout(cloudSyncTimer);clients=[];visits=[];visitReports=[];plans=[];jobs=[];invoices=[];payments=[];expenses=[];ownerCapital=[];accounts=[];vendors=[];vendorBills=[];vendorPayments=[];document.getElementById('authGate').style.display='flex';document.getElementById('authPassword').value='';}
async function authSignIn(){
 if(!supabaseClient){authStatus('Sign-in library could not load. Check your connection and reload.',true);return}
 const password=document.getElementById('authPassword').value;if(recoveryMode&&password.length<8){authStatus('Use at least 8 characters for the new password.',true);return}
 if(!password){authStatus('Enter your password.',true);return}
 authStatus(recoveryMode?'Updating password…':'Signing in…');
 try{const {error}=recoveryMode?await supabaseClient.auth.updateUser({password}):await supabaseClient.auth.signInWithPassword({email:ADMIN_EMAIL,password});if(error)throw error;if(recoveryMode){recoveryMode=false;document.querySelector('#authGate .primary').textContent='Sign in';await startCloudSession()}}catch(e){authStatus(e.message||'Sign-in failed.',true)}
}
async function authResetPassword(){try{if(!supabaseClient)throw Error('Sign-in library is unavailable. Reload the page.');const {error}=await supabaseClient.auth.resetPasswordForEmail(ADMIN_EMAIL,{redirectTo:location.origin+location.pathname});if(error)throw error;authStatus('Password reset requested. Check the admin email inbox.')}catch(e){authStatus(e.message,true)}}
async function authSignOut(){try{if(cloudReady){await cloudSyncNow();if(cloudDirty)throw Error('Some changes are not synced. Retry sync before signing out.')}const {error}=await supabaseClient.auth.signOut();if(error)throw error;resetWorkspace();authStatus('Signed out.')}catch(e){syncStatus(e.message,true)}}
async function startCloudSession(){
 if(sessionStarting||recoveryMode)return;sessionStarting=true;const epoch=sessionEpoch;
 try{
 const {data:{user},error:userError}=await supabaseClient.auth.getUser();if(userError)throw userError;if(epoch!==sessionEpoch)return;
 if(!user){resetWorkspace();return}if(user.email?.toLowerCase()!==ADMIN_EMAIL){await supabaseClient.auth.signOut();throw Error('Only the Aahana business admin can access this workspace.')}
 if(cloudReady&&cloudUser?.id===user.id)return;cloudUser=user;
 let {data:members,error}=await supabaseClient.from('organization_members').select('organization_id,role').eq('user_id',user.id);if(error)throw error;
 if(!members?.length){authStatus('Setting up your Aahana workspace…');const {error:bootstrapError}=await supabaseClient.rpc('bootstrap_aahana_workspace');if(bootstrapError)throw bootstrapError;const refreshed=await supabaseClient.from('organization_members').select('organization_id,role').eq('user_id',user.id);members=refreshed.data;if(refreshed.error)throw refreshed.error}
 if(epoch!==sessionEpoch)return;if(members?.length!==1)throw Error('Expected one business workspace. Ask the administrator to check membership.');
 cloudOrgId=members[0].organization_id;let backup=null;try{backup=JSON.parse(localStorage.getItem(cacheKey())||'null')}catch(e){}await cloudLoadData();if(backup?.pending&&backup.snapshot){restoreSnapshot(backup.snapshot);syncedBaselines=backup.baselines||{};cloudDirty=true;changeVersion++;syncStatus('Recovered unsynced changes from this browser. Use Retry sync.');persistCache()}if(epoch!==sessionEpoch)return;document.getElementById('authGate').style.display='none';renderAll();
 }catch(e){authStatus(e.message||'Unable to load workspace.',true)}finally{sessionStarting=false}
}
if(supabaseClient)supabaseClient.auth.onAuthStateChange((event,session)=>{
 if(event==='PASSWORD_RECOVERY'){recoveryMode=true;document.getElementById('authGate').style.display='flex';document.querySelector('#authGate .primary').textContent='Save new password';document.getElementById('authPassword').autocomplete='new-password';authStatus('Enter a new password of at least 8 characters.');return}
 if(!session){resetWorkspace();return}
 if(event==='SIGNED_IN'||event==='INITIAL_SESSION')setTimeout(()=>startCloudSession(),0);
});
const today=new Date(); today.setHours(0,0,0,0);
const iso=d=>{const x=new Date(d);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')};
const addDays=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x};
