let payments=[];
let expenses=[];
let ownerCapital=[];
let accounts=[{id:1,name:'Cash',type:'Cash',opening:0},{id:2,name:'Bank',type:'Bank',opening:0},{id:3,name:'UPI / Wallet',type:'UPI',opening:0},{id:4,name:'Petty Cash',type:'Petty Cash',opening:0}];
let modalType='';
const STORAGE_KEY='aahana_pest_control_data_v2';
const cacheKey=()=>STORAGE_KEY+':'+cloudUser?.id+':'+cloudOrgId;
let cloudReady=false,cloudHydrating=false,cloudSyncTimer=null,cloudSyncBusy=false;
function localSnapshot(){return {clients,visits,visitReports,plans,jobs,invoices,payments,expenses,ownerCapital,accounts,vendors,vendorBills,vendorPayments,erpRecords,historicalBills,taxPayments:erpRecords.filter(r=>r.kind==='tax_payment').map(r=>r.data),accountTransfers:erpRecords.filter(r=>r.kind==='account_transfer').map(r=>r.data)}}
let cloudDirty=false,changeVersion=0;
function syncStatus(message,error=false){let el=document.getElementById('syncStatus');if(!el){el=document.createElement('div');el.id='syncStatus';el.setAttribute('role','status');el.style.cssText='position:fixed;bottom:12px;right:12px;z-index:90;background:var(--bg);padding:10px;border:1px solid var(--border);border-radius:8px';document.body.append(el)}el.textContent=message;el.style.color=error?'var(--danger)':'var(--muted)'}
function persistCache(){if(!cloudUser||!cloudOrgId||!cloudReady)return;try{localStorage.setItem(cacheKey(),JSON.stringify({snapshot:localSnapshot(),pending:cloudDirty,baselines:syncedBaselines}))}catch(e){syncStatus('Browser backup could not be saved.',true)}}
function saveData(){if(!cloudReady||cloudHydrating)return;cloudDirty=true;changeVersion++;persistCache();clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>cloudSyncNow(),700)}
function cloudId(row){return row?.cloud_id||row?.id}
function localByCloudId(list,id){return list.find(x=>String(cloudId(x))===String(id))}
function syncDefinitions(){return [
{table:'clients',rows:clients,payloadFor:r=>({name:r.name,site:r.site,contact:r.contact,plan:r.plan,rule:r.rule,visits:r.visits,status:r.status,billing_details:r.billing||{}})},
{table:'service_plans',rows:plans,payloadFor:r=>({client_id:cloudId(clients.find(c=>c.id==r.client)),name:r.name,rule:r.rule,completed:r.completed,total:r.total,next_date:r.next})},
{table:'visits',rows:visits,payloadFor:r=>({client_id:cloudId(clients.find(c=>c.id==r.client)),date:r.date,time:r.time,plan:r.plan,status:r.status,technician:r.tech})},
{table:'visit_reports',rows:visitReports,payloadFor:r=>({visit_id:cloudId(visits.find(v=>v.id==r.visit)),report_date:r.date,work:r.work,materials:r.materials,client_status:r.clientStatus,followup:r.followup})},
{table:'jobs',rows:jobs,payloadFor:r=>({title:r.title,client_id:r.client?cloudId(clients.find(c=>c.id==r.client)):null,due:r.due,assignee:r.assignee,priority:r.priority,status:r.status,notes:r.notes})},
{table:'invoices',rows:invoices,payloadFor:r=>({invoice_no:r.no,client_id:cloudId(clients.find(c=>c.id==r.client)),invoice_date:r.date,taxable:r.taxable,gst:r.gst,total:r.total,billing_details:r.billing||{}})},
{table:'payments',rows:payments,payloadFor:r=>({invoice_id:cloudId(invoices.find(i=>i.id==r.invoice)),receipt:r.receipt,payment_date:r.date,amount:r.amount,mode:r.mode})},
{table:'expenses',rows:expenses,payloadFor:r=>({expense_date:r.date,category:r.category,vendor:r.vendor,description:r.description,account:r.account,amount:r.amount,gst:r.gst,receipt:r.receipt})},
{table:'accounts',rows:accounts,payloadFor:r=>({name:r.name,type:r.type,opening:r.opening})},
{table:'owner_capital',rows:ownerCapital,payloadFor:r=>({capital_date:r.date,amount:r.amount,mode:r.mode})},
{table:'vendors',rows:vendors,payloadFor:r=>({name:r.name,contact:r.contact,gstin:r.gstin})},
{table:'vendor_bills',rows:vendorBills,payloadFor:r=>({vendor_id:cloudId(vendors.find(v=>v.id==r.vendor)),bill_no:r.billNo,bill_date:r.date,amount:r.amount,gst:r.gst,description:r.description})},
{table:'vendor_payments',rows:vendorPayments,payloadFor:r=>({vendor_id:cloudId(vendors.find(v=>v.id==r.vendor)),payment_date:r.date,amount:r.amount,mode:r.mode})},
{table:'erp_records',rows:erpRecords,payloadFor:r=>({kind:r.kind,record_key:r.key,payload:r.data})}
]}
let syncedBaselines={},lastCloudRefresh=0;
function baselineKey(table,id){return table+':'+id}
function stableValue(value){if(Array.isArray(value))return value.map(stableValue);if(value&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().map(k=>[k,stableValue(value[k])]));return value}
function normalizedPayload(payload){const numeric=new Set(['visits','completed','total','taxable','gst','amount','opening']);return JSON.stringify(Object.keys(payload).sort().map(key=>[key,numeric.has(key)?Number(payload[key]||0):key==='time'?String(payload[key]||'').slice(0,5):stableValue(payload[key]??'')]))}
function projectPayload(remote,payload){return Object.fromEntries(Object.keys(payload).map(key=>[key,remote[key]??null]))}
function captureBaselines(out){syncedBaselines={};for(const {table,rows,payloadFor} of syncDefinitions()){for(const row of rows){const remote=out[table].find(r=>r.id===row.cloud_id);if(remote)syncedBaselines[baselineKey(table,row.cloud_id)]=projectPayload(remote,{organization_id:cloudOrgId,...payloadFor(row)})}}}
async function cloudSyncTable(table,rows,payloadFor){
 for(const row of rows){
 const payload={organization_id:cloudOrgId,...payloadFor(row)};
 const key=baselineKey(table,row.cloud_id),baseline=syncedBaselines[key];
 if(baseline&&normalizedPayload(payload)===normalizedPayload(baseline))continue;
 if(!row.cloud_id){row.cloud_id=crypto.randomUUID();persistCache()}
 const rowKey=baselineKey(table,row.cloud_id);
 for(const field of ['client_id','visit_id','invoice_id','vendor_id']){if(field in payload&&payload[field]!==null&&!payload[field])throw Error('Missing linked record in '+table+'. Sync its parent first.')}
 let query;
 if(baseline){
 query=supabaseClient.from(table).update(payload).eq('id',row.cloud_id).eq('organization_id',cloudOrgId);
 // Compare-and-set: if any business field changed since loading, never overwrite it.
 for(const [field,value] of Object.entries(baseline)){if(field==='organization_id')continue;query=value===null?query.is(field,null):query.eq(field,typeof value==='object'?JSON.stringify(value):value)}
 }else{
 // A client-generated UUID plus ignoreDuplicates makes interrupted inserts safe to retry.
 query=supabaseClient.from(table).upsert({id:row.cloud_id,...payload},{onConflict:'id',ignoreDuplicates:true});
 }
 const result=await query.select().maybeSingle();if(result.error)throw result.error;
 let saved=result.data;
 if(!saved&&!baseline){const existing=await supabaseClient.from(table).select('*').eq('id',row.cloud_id).eq('organization_id',cloudOrgId).maybeSingle();if(existing.error)throw existing.error;saved=existing.data;if(saved&&table==='invoices'&&row.numberPending)payload.invoice_no=saved.invoice_no;if(saved&&normalizedPayload(projectPayload(saved,payload))!==normalizedPayload(payload))throw Error('Sync conflict in '+table+'. Export your backup, then refresh and review the cloud record.')}
 if(!saved)throw Error('Sync conflict in '+table+'. Export your backup, then refresh and review the cloud record.');
 if(table==='invoices'&&row.numberPending){if(!saved.invoice_no||(saved.invoice_no.startsWith('DRAFT-')||saved.invoice_no==='Draft pending sync'))throw Error('Automatic invoice numbering is not configured. Keep this draft until the sequence migration is applied.');row.no=saved.invoice_no;row.numberPending=false;payload.invoice_no=saved.invoice_no;if(!document.activeElement?.closest('#financialERP input,#financialERP select'))renderAll();else renderFinance()}
 syncedBaselines[rowKey]=projectPayload(saved,payload);persistCache();
 }
}
async function cloudSyncNow(){
 if(!cloudReady||cloudHydrating||cloudSyncBusy||!cloudOrgId||!cloudDirty)return;
 const syncingVersion=changeVersion;syncStatus('Saving changes to cloud…');cloudSyncBusy=true;
 try{for(const {table,rows,payloadFor} of syncDefinitions())await cloudSyncTable(table,rows,payloadFor);if(changeVersion===syncingVersion)cloudDirty=false;persistCache();syncStatus(cloudDirty?'More changes waiting to sync.':'Saved to cloud.');}
 catch(e){persistCache();syncStatus('Cloud sync failed. Changes retained in this browser. '+(e.message||e),true)}
 finally{cloudSyncBusy=false;if(cloudDirty&&changeVersion!==syncingVersion){clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>cloudSyncNow(),700)}}
}
async function readCloudTable(table){let rows=[];for(let offset=0;;offset+=500){const {data,error}=await supabaseClient.from(table).select('*').eq('organization_id',cloudOrgId).order('id').range(offset,offset+499);if(error)throw error;rows.push(...(data||[]));if(!data||data.length<500)return rows}}
async function refreshCloudData(manual=false){
 if(!cloudReady||cloudSyncBusy||cloudHydrating||document.getElementById('modal').classList.contains('open')||document.activeElement?.closest('#financialERP input,#financialERP select'))return;
 if(cloudDirty){if(manual)syncStatus('You have unsynced changes. Retry sync, or export a backup before reloading cloud data.',true);return}
 if(!manual&&Date.now()-lastCloudRefresh<15000)return;
 try{await cloudLoadData();renderAll()}catch(e){syncStatus('Cloud refresh failed. Current data is still available. '+e.message,true)}
}
function exportBackup(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),organizationId:cloudOrgId,pending:cloudDirty,snapshot:localSnapshot()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='aahana-backup-'+iso(today)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function reloadCloudData(){if(cloudSyncBusy||cloudHydrating)return;if(cloudDirty&&!confirm('Discard unsynced changes in this browser and reload cloud data? Export a backup first if you need those changes.'))return;try{await cloudLoadData();cloudDirty=false;persistCache();renderAll()}catch(e){syncStatus('Could not reload cloud data. '+e.message,true)}}
async function cloudLoadData(){if(!cloudOrgId)return;cloudHydrating=true;try{const tables=['clients','service_plans','visits','visit_reports','jobs','invoices','payments','expenses','accounts','owner_capital','vendors','vendor_bills','vendor_payments','erp_records','historical_billing'];const out={};for(const table of tables){out[table]=await readCloudTable(table)}accounts=out.accounts.map((r,index)=>({...r,id:index+1,cloud_id:r.id,opening:Number(r.opening)}));vendors=out.vendors.map((r,index)=>({...r,id:index+1,cloud_id:r.id}));clients=out.clients.map((r,index)=>({...r,billing:r.billing_details||{},id:index+1,cloud_id:r.id}));const clientLocal=r=>localByCloudId(clients,r.client_id)?.id;plans=out.service_plans.map((r,index)=>({id:index+1,cloud_id:r.id,client:clientLocal(r),name:r.name,rule:r.rule,completed:r.completed,total:r.total,next:r.next_date}));visits=out.visits.map((r,index)=>({id:index+1,cloud_id:r.id,client:clientLocal(r),date:r.date,time:r.time,plan:r.plan,status:r.status,tech:r.technician}));visitReports=out.visit_reports.map((r,index)=>({id:index+1,cloud_id:r.id,visit:localByCloudId(visits,r.visit_id)?.id,date:r.report_date,work:r.work,materials:r.materials,clientStatus:r.client_status,followup:r.followup}));jobs=out.jobs.map((r,index)=>({id:index+1,cloud_id:r.id,title:r.title,client:clientLocal(r),due:r.due,assignee:r.assignee,priority:r.priority,status:r.status,notes:r.notes}));invoices=out.invoices.map((r,index)=>({id:index+1,cloud_id:r.id,no:r.invoice_no,client:clientLocal(r),date:r.invoice_date,taxable:Number(r.taxable),gst:Number(r.gst),total:Number(r.total),billing:r.billing_details||{},paid:0}));payments=out.payments.map((r,index)=>({id:index+1,cloud_id:r.id,invoice:localByCloudId(invoices,r.invoice_id)?.id,receipt:r.receipt,date:r.payment_date,amount:Number(r.amount),mode:r.mode}));expenses=out.expenses.map((r,index)=>({id:index+1,cloud_id:r.id,date:r.expense_date,category:r.category,vendor:r.vendor||'',description:r.description,account:r.account,amount:Number(r.amount),gst:Number(r.gst),receipt:r.receipt||''}));ownerCapital=out.owner_capital.map((r,index)=>({id:index+1,cloud_id:r.id,date:r.capital_date,amount:Number(r.amount),mode:r.mode}));vendorBills=out.vendor_bills.map((r,index)=>({id:index+1,cloud_id:r.id,vendor:localByCloudId(vendors,r.vendor_id)?.id,billNo:r.bill_no,date:r.bill_date,amount:Number(r.amount),gst:Number(r.gst),description:r.description}));vendorPayments=out.vendor_payments.map((r,index)=>({id:index+1,cloud_id:r.id,vendor:localByCloudId(vendors,r.vendor_id)?.id,date:r.payment_date,amount:Number(r.amount),mode:r.mode}));historicalBills=out.historical_billing.map(r=>({...r,client:localByCloudId(clients,r.client_id)?.id}));erpRecords=out.erp_records.map((r,index)=>({id:index+1,cloud_id:r.id,kind:r.kind,key:r.record_key,data:r.payload}));captureBaselines(out);lastCloudRefresh=Date.now();cloudReady=true;persistCache();syncStatus('Cloud workspace loaded.')}catch(e){throw e}finally{cloudHydrating=false}}
let vendors=[];
let vendorBills=[];
let vendorPayments=[];
function clientName(id){return clients.find(c=>c.id==id)?.name||'Unknown'}
function fmt(d){return new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}
function statusBadge(s){const label=s==='done'?'Completed':s==='overdue'?'Overdue':'Due';return `<span class="badge ${s==='done'?'green':s==='overdue'?'red':'yellow'}">${label}</span>`}
function render(){visits.forEach(v=>{if(v.status!=='done')v.status=v.date<iso(today)?'overdue':'due'});
const q=(document.getElementById('search')?.value||'').toLowerCase(); const sf=document.getElementById('statusFilter')?.value||'all';
let filtered=visits.filter(v=>{const c=clientName(v.client).toLowerCase();return(!q||c.includes(q)||v.plan.toLowerCase().includes(q))&&(sf==='all'||v.status===sf)});
document.getElementById('kToday').textContent=visits.filter(v=>v.date===iso(today)).length;
document.getElementById('kDue').textContent=visits.filter(v=>v.status==='due'||v.status==='overdue').length;
document.getElementById('kClients').textContent=clients.filter(c=>c.status==='Active').length;
document.getElementById('kWA').textContent=visits.filter(v=>v.status==='due'||v.status==='overdue').length;
document.getElementById('visitRows').innerHTML=filtered.map(v=>`<tr><td><b>${escapeHtml(clientName(v.client))}</b><div style="font-size:10px;color:var(--muted)">${escapeHtml(clients.find(c=>c.id==v.client)?.site||'')}</div></td><td>${escapeHtml(v.plan)}</td><td>${fmt(v.date)} · ${escapeHtml(v.time)}</td><td>${escapeHtml(clients.find(c=>c.id==v.client)?.rule||'')}</td><td>${statusBadge(v.status)}</td><td><button class="mini ${v.status!=='done'?'primary':''}" onclick="completeVisit(${v.id})">${v.status==='done'?'View':'Complete'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching visits.</td></tr>';
document.getElementById('waList').innerHTML=visits.filter(v=>v.status!=='done').slice(0,5).map(v=>`<div class="item"><div class="item-main"><b>${escapeHtml(clientName(v.client))}</b><div>${v.status==='overdue'?'Overdue visit':'Reminder'} · ${fmt(v.date)} · ${escapeHtml(v.time)}</div></div><div class="item-side"><button class="mini" onclick="sendWA(${v.id})">Send</button></div></div>`).join('')||'<div class="empty">Queue is clear.</div>';
document.getElementById('clientRows').innerHTML=clients.map(c=>`<tr><td><b>${escapeHtml(c.name)}</b></td><td>${escapeHtml(c.site)}</td><td>${escapeHtml(c.contact)}</td><td>${escapeHtml(c.plan)}</td><td>${c.visits}</td><td><span class="badge green">${escapeHtml(c.status)}</span></td></tr>`).join('');
document.getElementById('planRows').innerHTML=plans.map(p=>`<tr><td>${escapeHtml(clientName(p.client))}</td><td><b>${escapeHtml(p.name)}</b></td><td>${escapeHtml(p.rule)}</td><td>${p.completed}</td><td>${Math.max(0,p.total-p.completed)}</td><td>${fmt(p.next)}</td></tr>`).join('');
let days='';for(let i=-1;i<=6;i++){let d=iso(addDays(today,i)), vs=visits.filter(v=>v.date===d);if(!vs.length)continue;days+=`<div class="day"><div class="day-title">${d===iso(today)?'TODAY':new Date(d+'T00:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'2-digit',month:'short'})}</div>${vs.map(v=>`<div class="visit"><div><div class="visit-name">${escapeHtml(clientName(v.client))}</div><div class="visit-meta">${escapeHtml(v.time)} · ${escapeHtml(v.plan)} · ${escapeHtml(v.tech)}</div></div><div class="visit-actions">${statusBadge(v.status)} <button class="mini ${v.status!=='done'?'primary':''}" onclick="completeVisit(${v.id})">${v.status==='done'?'Done':'Update'}</button></div></div>`).join('')}</div>`}document.getElementById('timeline').innerHTML=days||'<div class="empty">No visits scheduled.</div>';
let queue=visits.filter(v=>v.status!=='done');document.getElementById('queueCount').textContent=queue.length+' pending';document.getElementById('waFull').innerHTML=queue.map(v=>`<div class="item"><div class="item-main"><b>${escapeHtml(clientName(v.client))} — ${v.status==='overdue'?'Overdue alert':'Visit reminder'}</b><div>Scheduled ${fmt(v.date)} at ${escapeHtml(v.time)}. Message ready.</div></div><div class="item-side"><span class="wa">WhatsApp</span><br><button class="mini" onclick="sendWA(${v.id})">Send now</button></div></div>`).join('')||'<div class="empty">No pending WhatsApp messages.</div>';
document.getElementById('rPlanned').textContent=visits.length;document.getElementById('rDone').textContent=visits.filter(v=>v.status==='done').length;document.getElementById('rRate').textContent=Math.round(visits.filter(v=>v.status==='done').length/Math.max(1,visits.length)*100)+'%';document.getElementById('rExceptions').textContent=visits.filter(v=>v.status==='overdue').length;
}
function nextPlanDate(plan,date){const d=new Date(date+'T00:00:00');if(/3 months/i.test(plan.rule)){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+3);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return iso(d)}if(/daily|every day/i.test(plan.rule))return iso(addDays(d,1));if(/4.*month/i.test(plan.rule))return iso(addDays(d,7));return plan.next}
function completeVisit(id){const v=visits.find(x=>x.id===id);if(!v)return;if(v.status==='done'){const r=visitReports.find(x=>x.visit===id);alert(r?'Visit report: '+r.work+'\nMaterials: '+r.materials+'\nClient status: '+r.clientStatus+'\nFollow-up: '+r.followup:'Visit is completed.');return}const work=prompt('Treatment / work completed:','General pest-control treatment')||'General pest-control treatment',materials=prompt('Chemicals / materials used:','')||'',clientStatus=prompt('Client status: Satisfied / Follow-up needed / Not available','Satisfied')||'Satisfied',followup=prompt('Follow-up / next action:','No follow-up required')||'No follow-up required';v.status='done';visitReports.push({id:Math.max(0,...visitReports.map(r=>r.id))+1,visit:id,date:iso(today),work,materials,clientStatus,followup});const p=plans.find(x=>x.client===v.client&&x.name===v.plan);if(p){p.completed=Math.min(p.total,p.completed+1);p.next=nextPlanDate(p,v.date)}render();alert('Visit completed and report recorded.');}
function waMessage(v){return v.status==='overdue'?String('Aahana Pest Control: Visit for '+clientName(v.client)+' is overdue. Please update the service status.'):String('Aahana Pest Control reminder: service visit for '+clientName(v.client)+' is scheduled for '+fmt(v.date)+' at '+v.time+'.')}
async function copyMessage(text){try{if(!navigator.clipboard)throw Error('Clipboard is unavailable. Use a secure HTTPS page.');await navigator.clipboard.writeText(text);alert('Message copied. Open WhatsApp and paste/send it.')}catch(e){alert('Could not copy the message: '+e.message)}}
function sendWA(id){const v=visits.find(x=>x.id===id);if(v)return copyMessage(waMessage(v))}
function copyAllWA(){const queue=visits.filter(v=>v.status!=='done');if(!queue.length){alert('No pending reminders.');return}return copyMessage(queue.map(waMessage).join('\n\n'))}
function renderVisitReports(){document.getElementById('visitReportRows').innerHTML=visitReports.slice().sort((a,b)=>b.id-a.id).map(r=>{const v=visits.find(x=>x.id===r.visit);return '<tr><td>'+fmt(r.date)+'</td><td><b>'+escapeHtml(clientName(v?.client))+'</b></td><td>'+escapeHtml(v?.tech||'—')+'</td><td>'+escapeHtml(r.work)+'</td><td>'+escapeHtml(String(r.materials||'—'))+'</td><td>'+escapeHtml(r.clientStatus)+'</td><td>'+escapeHtml(r.followup)+'</td></tr>'}).join('')||'<tr><td colspan="7" class="empty">No completed visit reports yet.</td></tr>'}
function renderJobs(){const todayIso=iso(today),open=jobs.filter(j=>j.status!=='done');document.getElementById('jOpen').textContent=open.length;document.getElementById('jToday').textContent=open.filter(j=>j.due===todayIso).length;document.getElementById('jOverdue').textContent=open.filter(j=>j.due<todayIso).length;document.getElementById('jDone').textContent=jobs.filter(j=>j.status==='done').length;document.getElementById('jobRows').innerHTML=jobs.map(j=>`<tr><td><b>${escapeHtml(j.title)}</b><div style="font-size:10px;color:var(--muted)">${escapeHtml(j.notes||'')}</div></td><td>${escapeHtml(j.client?clientName(j.client):'Internal')}</td><td>${fmt(j.due)}</td><td>${escapeHtml(j.assignee)}</td><td>${j.priority==='High'?'<span class="badge red">High</span>':'<span class="badge gray">Normal</span>'}</td><td>${j.status==='done'?'<span class="badge green">Completed</span>':j.due<todayIso?'<span class="badge red">Overdue</span>':'<span class="badge yellow">Open</span>'}</td><td><button class="mini ${j.status!=='done'?'primary':''}" onclick="completeJob(${j.id})">${j.status==='done'?'Done':'Complete'}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No jobs added.</td></tr>'}
function completeJob(id){const j=jobs.find(x=>x.id===id);if(!j)return;j.status='done';renderJobs();alert('Job marked completed.');}
function addJob(){openModal('job')}
function renderReports(){
 const period=document.getElementById('reportPeriod')?.value||'all',inPeriod=d=>period!=='month'||String(d).slice(0,7)===iso(today).slice(0,7);
 const state=localSnapshot(),current=AahanaFinance.summary(state),selected=AahanaFinance.summary({...state,invoices:invoices.filter(i=>inPeriod(i.date)),payments:payments.filter(p=>inPeriod(p.date)),expenses:expenses.filter(e=>inPeriod(e.date)),vendorBills:vendorBills.filter(b=>inPeriod(b.date))});
 const amounts={rRevenue:selected.revenue,rCollected:selected.collected,rProfit:selected.profit,rOutstanding:current.outstanding,rFinRevenue:selected.revenue,rFinExpenses:selected.operatingExpenses,rFinProfit:selected.profit,rGST:Math.max(0,selected.netGST),rCash:current.cash,rReceivable:current.receivable,rPayable:current.payable};
 Object.entries(amounts).forEach(([id,amount])=>document.getElementById(id).textContent=money(amount));
 const planned=visits.filter(v=>inPeriod(v.date)),done=planned.filter(v=>v.status==='done').length;
 document.getElementById('rPlanned').textContent=planned.length;document.getElementById('rDone').textContent=done;document.getElementById('rRate').textContent=Math.round(done/Math.max(1,planned.length)*100)+'%';document.getElementById('rExceptions').textContent=planned.filter(v=>v.status==='overdue').length+jobs.filter(j=>j.status!=='done').length;
 document.getElementById('reportClientRows').innerHTML=clients.map(c=>{const ci=invoices.filter(i=>i.client===c.id&&inPeriod(i.date)),cb=AahanaFinance.sum(ci,'total'),cp=AahanaFinance.sum(payments.filter(p=>ci.some(i=>i.id===p.invoice)),'amount'),co=AahanaFinance.sum(ci,i=>AahanaFinance.outstandingFor(i,payments)),rate=cb?Math.round(cp/cb*100):0;return '<tr><td><b>'+escapeHtml(c.name)+'</b></td><td>'+ci.length+'</td><td>'+money(cb)+'</td><td>'+money(cp)+'</td><td>'+money(co)+'</td><td>'+rate+'%</td></tr>'}).join('')||'<tr><td colspan="6" class="empty">No clients yet.</td></tr>';
 const balances=accountBalances();document.getElementById('reportAccountRows').innerHTML=accounts.map(a=>'<tr><td><b>'+escapeHtml(a.name)+'</b></td><td>'+money(balances[a.id])+'</td></tr>').join('');
}
function money(n){return '₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}
function renderFinance(){const {billed,collected,outstanding,gstCollected,expenseGross,expenseGST,vendorBilled,vendorPaid,vendorGST,revenue,operatingExpenses,profit,inputGST,netGST,receivable,payable,capital,cash,assets,equity,liabilities,balanceCheck}=AahanaFinance.summary(localSnapshot());const paidByInvoice=id=>AahanaFinance.paidFor(id,payments);document.getElementById('bBilled').textContent=money(billed);document.getElementById('bCollected').textContent=money(collected);document.getElementById('bOutstanding').textContent=money(outstanding);document.getElementById('bInvoices').textContent=invoices.length;document.getElementById('billingRows').innerHTML=invoices.map(i=>{const paid=paidByInvoice(i.id),balance=AahanaFinance.outstandingFor(i,payments);return `<tr><td><b>${escapeHtml(i.no)}</b><br><small>FY ${AahanaERP.financialYear(i.date)}</small></td><td>${escapeHtml(clientName(i.client))}</td><td>${fmt(i.date)}</td><td>${money(i.taxable)}</td><td>${money(i.gst)}</td><td>${money(i.total)}</td><td>${money(paid)}</td><td>${money(balance)}</td><td>${balance===0?'<span class="badge green">Paid</span>':'<span class="badge yellow">Pending</span>'}</td><td><button class="mini ${balance>0?'primary':''}" onclick="recordPayment(${i.id})">${balance>0?'Record payment':'Paid'}</button> <button class="mini" onclick="issueReceipt(${i.id})">Receipt</button> <button class="mini" onclick="previewInvoice(${i.id})">Invoice</button></td></tr>`}).join('')||'<tr><td colspan="10" class="empty">No invoices yet.</td></tr>';document.getElementById('paymentRows').innerHTML=payments.slice().sort((a,b)=>b.id-a.id).map(p=>{const i=invoices.find(x=>x.id===p.invoice);return `<tr><td><b>${escapeHtml(p.receipt)}</b></td><td>${fmt(p.date)}</td><td>${escapeHtml(i?.no||'—')}</td><td>${escapeHtml(i?clientName(i.client):'—')}</td><td>${money(p.amount)}</td><td>${escapeHtml(p.mode)}</td><td><button class="mini" onclick="issueReceipt(${p.invoice},${p.id})">Receipt</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No payments recorded yet.</td></tr>';document.getElementById('aRevenue').textContent=money(revenue);document.getElementById('aExpenses').textContent=money(operatingExpenses);document.getElementById('aProfit').textContent=money(profit);document.getElementById('aCash').textContent=money(cash);document.getElementById('plRevenue').textContent=money(revenue);document.getElementById('plExpenses').textContent=money(operatingExpenses);document.getElementById('plProfit').textContent=money(profit);document.getElementById('bsCash').textContent=money(cash);document.getElementById('bsReceivable').textContent=money(receivable);document.getElementById('bsInputGST').textContent=money(inputGST);document.getElementById('bsAssets').textContent=money(assets);document.getElementById('bsPayables').textContent=money(payable);document.getElementById('bsGST').textContent=money(gstCollected);document.getElementById('bsEquity').textContent=money(equity);document.getElementById('bsCheck').textContent=money(balanceCheck);document.getElementById('gCollected').textContent=money(gstCollected);document.getElementById('gPaid').textContent=money(inputGST);document.getElementById('gPayable').textContent=money(Math.max(0,netGST));document.getElementById('gstOut').textContent=money(gstCollected);document.getElementById('gstIn').textContent=money(inputGST);document.getElementById('gstNet').textContent=money(netGST);document.getElementById('ledgerRows').innerHTML=[...invoices.map(i=>({date:i.date,type:'Income',category:'Client billing',description:i.no+' — '+clientName(i.client),amount:i.taxable,gst:i.gst})),...expenses.map(e=>({date:e.date,type:'Expense',category:e.category,description:e.description,amount:-Math.max(0,e.amount-e.gst),gst:e.gst})),...vendorBills.map(b=>({date:b.date,type:'Purchase',category:'Supplier bill',description:b.billNo+' — '+(vendors.find(v=>v.id===b.vendor)?.name||'Supplier'),amount:-Math.max(0,b.amount-b.gst),gst:b.gst}))].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${fmt(x.date)}</td><td>${escapeHtml(x.type)}</td><td>${escapeHtml(x.category)}</td><td>${escapeHtml(x.description)}</td><td>${money(x.amount)}</td><td>${money(x.gst)}</td></tr>`).join('')}
function accountIdByName(name){return AahanaFinance.resolveAccount(accounts,name)}
function accountBalances(){return AahanaFinance.accountBalances(localSnapshot())}
const financeCore=renderFinance;
renderFinance=function(){financeCore();renderAccountRegister()}
function addAccount(){const name=prompt('Account: Cash / Bank / UPI / Petty Cash','Bank')||'';const account=accounts.find(a=>a.name.toLowerCase().includes(name.trim().toLowerCase())||name.trim().toLowerCase().includes(a.type.toLowerCase()));if(!account){alert('Choose one of the four existing accounts: Cash, Bank, UPI or Petty Cash.');return}const opening=Number(prompt('Opening balance for '+account.name+':',String(account.opening||0))||0);if(!Number.isFinite(opening)||opening<0){alert('Opening balance cannot be negative.');return}account.opening=opening;renderFinance();renderAccountRegister();alert(account.name+' opening balance updated.')}
function renderAccountRegister(){let card=document.getElementById('accountRegister');if(!card){document.getElementById('accounting').insertAdjacentHTML('afterbegin','<div class="card" id="accountRegister" style="margin-bottom:16px"><div class="card-head"><h3>Cash / Bank / UPI / Petty Cash</h3><button class="mini primary" onclick="addAccount()">+ Account</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Account</th><th>Opening</th><th>Current balance</th></tr></thead><tbody id="accountRows"></tbody></table></div></div>')}const b=accountBalances();document.getElementById('accountRows').innerHTML=accounts.map(a=>'<tr><td><b>'+escapeHtml(a.name)+'</b></td><td>'+money(a.opening)+'</td><td>'+money(b[a.id])+'</td></tr>').join('')}
function addCapital(){const amount=Number(prompt('Owner capital introduced:','0')||0);if(!Number.isFinite(amount)||amount<=0){alert('Enter a capital amount greater than zero.');return}const mode=prompt('Capital account: Cash / Bank / UPI','Bank')||'Bank';ownerCapital.push({id:Math.max(0,...ownerCapital.map(c=>c.id))+1,date:iso(today),amount,mode});renderFinance();alert('Owner capital recorded.');}
function addInvoice(){openModal('invoice')}
function addVendor(){const name=prompt('Supplier / vendor name:','')?.trim()||'';if(!name){alert('Enter a supplier name.');return}const contact=prompt('Contact:','')||'',gstin=prompt('GSTIN (optional):','')||'';vendors.push({id:Math.max(0,...vendors.map(v=>v.id))+1,name,contact,gstin});renderVendorRegister();alert('Supplier added.')}
function addVendorBill(){if(!vendors.length){alert('Add a supplier first.');return}const choices=vendors.map(v=>v.id+': '+v.name).join('\n'),vendorId=Number(prompt('Supplier ID:\n'+choices,String(vendors[0].id))||0),vendor=vendors.find(v=>v.id===vendorId);if(!vendor){alert('Supplier not found.');return}const billNo=prompt('Supplier bill number:','PUR-'+String(vendorBills.length+1).padStart(3,'0'))||'',amount=Number(prompt('Total bill amount:','0')||0),gst=Number(prompt('GST included in supplier bill:','0')||0),description=prompt('Purchase / bill description:','Chemicals / equipment')||'Purchase';if(!Number.isFinite(amount)||!Number.isFinite(gst)||amount<=0||gst<0||gst>amount){alert('Enter a valid bill amount and GST.');return}if(vendorBills.some(b=>b.billNo===billNo)){alert('Supplier bill number already exists.');return}vendorBills.push({id:Math.max(0,...vendorBills.map(b=>b.id))+1,vendor:vendorId,billNo,date:iso(today),amount,gst,description});renderVendorRegister();alert('Supplier bill recorded.')}
function recordVendorPayment(vendorId){const billed=vendorBills.filter(b=>b.vendor===vendorId).reduce((s,b)=>s+b.amount,0),paid=vendorPayments.filter(p=>p.vendor===vendorId).reduce((s,p)=>s+p.amount,0),remaining=Math.max(0,billed-paid);if(remaining<=0){alert('No supplier balance is currently due.');return}const amount=Number(prompt('Payment amount. Outstanding: '+money(remaining),String(remaining))||0);if(!amount||amount<=0||amount>remaining){alert('Enter a valid amount up to '+money(remaining)+'.');return}const mode=prompt('Payment mode: Cash / UPI / Bank / Cheque','Bank')||'Bank';vendorPayments.push({id:Math.max(0,...vendorPayments.map(p=>p.id))+1,vendor:vendorId,date:iso(today),amount,mode});renderVendorRegister();alert('Supplier payment recorded.')}
function renderVendorRegister(){let card=document.getElementById('vendorRegister');if(!card){document.getElementById('accounting').insertAdjacentHTML('beforeend','<div class="card" id="vendorRegister" style="margin-top:16px"><div class="card-head"><h3>Supplier / Vendor Accounts</h3><button class="mini primary" onclick="addVendorBill()">+ Supplier bill</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Contact</th><th>Billed</th><th>Paid</th><th>Outstanding</th><th>Action</th></tr></thead><tbody id="vendorRows"></tbody></table></div><div class="card-head"><h3>Supplier Bill Register</h3><span>Purchases & input GST</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Supplier</th><th>Bill</th><th>Description</th><th>Amount</th><th>GST</th></tr></thead><tbody id="vendorBillRows"></tbody></table></div></div>')}document.getElementById('vendorRows').innerHTML=vendors.map(v=>{const billed=vendorBills.filter(b=>b.vendor===v.id).reduce((s,b)=>s+b.amount,0),paid=vendorPayments.filter(p=>p.vendor===v.id).reduce((s,p)=>s+p.amount,0),outstanding=Math.max(0,billed-paid);return '<tr><td><b>'+escapeHtml(v.name)+'</b></td><td>'+escapeHtml(v.contact)+'</td><td>'+money(billed)+'</td><td>'+money(paid)+'</td><td>'+money(outstanding)+'</td><td><button class="mini '+(outstanding?'primary':'')+'" onclick="recordVendorPayment('+v.id+')">'+(outstanding?'Pay supplier':'No due')+'</button></td></tr>'}).join('')||'<tr><td colspan="6" class="empty">No suppliers added.</td></tr>';document.getElementById('vendorBillRows').innerHTML=vendorBills.slice().sort((a,b)=>b.id-a.id).map(b=>'<tr><td>'+fmt(b.date)+'</td><td>'+escapeHtml(vendors.find(v=>v.id===b.vendor)?.name)+'</td><td>'+escapeHtml(b.billNo)+'</td><td>'+escapeHtml(b.description)+'</td><td>'+money(b.amount)+'</td><td>'+money(b.gst)+'</td></tr>').join('')||'<tr><td colspan="6" class="empty">No supplier bills recorded.</td></tr>'}
function setupVendorButton(){if(document.getElementById('vendorAddBtn'))return;document.querySelector('#accounting .page-head').insertAdjacentHTML('beforeend','<button class="btn" id="vendorAddBtn" onclick="addVendor()">+ Supplier</button>')}
function recordPayment(id){
 const invoice=invoices.find(i=>i.id===id);if(!invoice)return;
 const remaining=AahanaFinance.outstandingFor(invoice,payments);if(remaining<=0){alert('This invoice is already fully paid.');return}
 if(!accounts.length){alert('Set up payment accounts first.');return}
 modalType='payment';document.getElementById('modalTitle').textContent='Record payment · '+invoice.no;
 document.getElementById('modalBody').innerHTML='<input id="mPaymentInvoice" type="hidden" value="'+id+'"><p>Outstanding: <b>'+money(remaining)+'</b></p><div class="field"><label for="mPaymentAmount">Amount received</label><input id="mPaymentAmount" type="number" min="0.01" step="0.01" value="'+remaining+'"></div><div class="field"><label for="mPaymentDate">Payment date</label><input id="mPaymentDate" type="date" value="'+iso(today)+'"></div><div class="field"><label for="mPaymentReceipt">Receipt number</label><input id="mPaymentReceipt" value="'+AahanaFinance.nextNumber(payments,'receipt','REC')+'"></div><div class="field"><label for="mPaymentAccount">Received into account</label><select id="mPaymentAccount">'+accounts.map(a=>'<option value="'+a.id+'">'+escapeHtml(a.name)+'</option>').join('')+'</select></div>';
 document.getElementById('modal').classList.add('open');
}
function savePaymentModal(){
 try{
 const id=Number(document.getElementById('mPaymentInvoice').value),invoice=invoices.find(i=>i.id===id),amount=AahanaFinance.parseAmount(document.getElementById('mPaymentAmount').value),date=document.getElementById('mPaymentDate').value,receipt=document.getElementById('mPaymentReceipt').value.trim(),account=accounts.find(a=>a.id===Number(document.getElementById('mPaymentAccount').value));
 if(!invoice||!account)throw Error('Select an invoice and receiving account.');
 if(!AahanaFinance.validDate(date)||date<invoice.date||date>iso(today))throw Error('Use a valid payment date on or after the invoice date and no later than today.');
 if(!receipt||payments.some(p=>String(p.receipt).trim().toLowerCase()===receipt.toLowerCase()))throw Error('Enter a unique receipt number.');
 const remaining=AahanaFinance.outstandingFor(invoice,payments);if(amount<=0||AahanaFinance.paise(amount)>AahanaFinance.paise(remaining))throw Error('Enter a positive amount up to '+money(remaining)+'.');
 payments.push({id:Math.max(0,...payments.map(p=>p.id))+1,invoice:id,receipt,date,amount,mode:account.name});closeModal();
 }catch(e){alert(e.message)}
}
function showDocument(title,html){modalType='document';document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML='<div class="financial-document">'+html+'</div>';const button=document.querySelector('.modal-foot .primary');button.textContent='Print / Save PDF';button.setAttribute('onclick','window.print()');document.getElementById('modal').classList.add('open')}
function issueReceipt(invoiceId,paymentId=null){
 const invoice=invoices.find(i=>i.id===invoiceId);if(!invoice)return;
 const receipt=paymentId===null?payments.filter(p=>p.invoice===invoiceId).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id)[0]:payments.find(p=>p.id===paymentId&&p.invoice===invoiceId);
 if(!receipt){alert('No payment has been recorded for this invoice yet.');return}
 showDocument('Payment receipt', '<h2>Aahana Pest Control</h2><h3>'+escapeHtml(receipt.receipt)+'</h3><p>Date: '+escapeHtml(receipt.date)+'</p><p>Received from: '+escapeHtml(clientName(invoice.client))+'</p><p>Invoice: '+escapeHtml(invoice.no)+'</p><p>Amount received: <b>'+money(receipt.amount)+'</b></p><p>Received into: '+escapeHtml(receipt.mode)+'</p><p>Current invoice outstanding: '+money(AahanaFinance.outstandingFor(invoice,payments))+'</p>');
}
function previewInvoice(id){const invoice=invoices.find(i=>i.id===id);if(!invoice)return;const client=clients.find(c=>c.id===invoice.client);showDocument('Invoice summary','<h2>Aahana Pest Control</h2><h3>'+escapeHtml(invoice.no)+'</h3><p>Date: '+escapeHtml(invoice.date)+' · Service month: '+escapeHtml(invoice.billing?.serviceMonth||invoice.date.slice(0,7))+'</p><p>Client: '+escapeHtml(client?.name||'Unknown')+'</p><p>Site: '+escapeHtml(client?.site||'')+'</p><table class="table"><tbody><tr><th>Taxable amount</th><td>'+money(invoice.taxable)+'</td></tr><tr><th>Recorded GST</th><td>'+money(invoice.gst)+'</td></tr><tr><th>Total</th><td>'+money(invoice.total)+'</td></tr><tr><th>Paid</th><td>'+money(AahanaFinance.paidFor(invoice.id,payments))+'</td></tr><tr><th>Outstanding</th><td>'+money(AahanaFinance.outstandingFor(invoice,payments))+'</td></tr></tbody></table><p>Invoice summary. Business GST details and the final tax-invoice format will be configured before issuing statutory invoices.</p>')}
function addExpense(){const category=prompt('Expense category: Petty cash / Travel / Chemicals / Salaries / Office / Equipment / Miscellaneous','Petty cash')||'Miscellaneous',vendor=prompt('Vendor / payee:','')||'',description=prompt('Description:','Business expense')||'Business expense',account=prompt('Payment account: Cash / Petty Cash / Bank / UPI / Cheque','Cash / Petty Cash')||'Cash / Petty Cash',amount=Number(prompt('Total expense amount:','0')||0),gst=Number(prompt('GST included in expense:','0')||0),receipt=prompt('Receipt / bill reference:','')||'';if(!Number.isFinite(amount)||!Number.isFinite(gst)||amount<=0||gst<0||gst>amount){alert('Enter a valid expense amount and GST amount.');return}expenses.push({id:Math.max(0,...expenses.map(e=>e.id))+1,date:iso(today),category,vendor,description,account,amount,gst,receipt});renderFinance();renderExpenseRegister();alert('Expense voucher recorded.')}
function renderExpenseRegister(){let card=document.getElementById('expenseRegister');if(!card){document.getElementById('accounting').insertAdjacentHTML('beforeend','<div class="card" id="expenseRegister" style="margin-top:16px"><div class="card-head"><h3>Expense & Petty Cash Register</h3><span>Business payments</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Category</th><th>Vendor / Payee</th><th>Description</th><th>Account</th><th>Amount</th><th>GST</th><th>Receipt</th></tr></thead><tbody id="expenseRows"></tbody></table></div></div>')}document.getElementById('expenseRows').innerHTML=expenses.slice().sort((a,b)=>b.id-a.id).map(e=>'<tr><td>'+fmt(e.date)+'</td><td>'+escapeHtml(e.category)+'</td><td>'+escapeHtml(String(e.vendor||'—'))+'</td><td>'+escapeHtml(e.description)+'</td><td>'+escapeHtml(String(e.account||'Cash'))+'</td><td>'+money(e.amount)+'</td><td>'+money(e.gst)+'</td><td>'+escapeHtml(String(e.receipt||'—'))+'</td></tr>').join('')||'<tr><td colspan="8" class="empty">No expenses recorded.</td></tr>'}
function openModal(type){if(['visit','plan','invoice'].includes(type)&&!clients.length){alert('Add a client first.');return}modalType=type;document.getElementById('modal').classList.add('open');let body=document.getElementById('modalBody');let title=document.getElementById('modalTitle');if(type==='client'){title.textContent='Add client';body.innerHTML='<div class="field"><label>Client name</label><input id="mName" placeholder="e.g. Hotel Sunrise"></div><div class="field"><label>Service site</label><input id="mSite" placeholder="Site / address"></div><div class="field"><label>WhatsApp contact</label><input id="mContact" placeholder="+91 …"></div><div class="field"><label>Service plan</label><input id="mPlan" placeholder="e.g. 4 visits / month"></div>'}else if(type==='visit'){title.textContent='Schedule visit';body.innerHTML='<div class="field"><label>Client</label><select id="mClient">'+clients.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')+'</select></div><div class="field"><label>Date</label><input id="mDate" type="date" value="'+iso(today)+'"></div><div class="field"><label>Time</label><input id="mTime" type="time" value="09:30"></div><div class="field"><label>Technician</label><input id="mTech" value="Raj"></div>'}else if(type==='plan'){title.textContent='New service plan';body.innerHTML='<div class="field"><label>Client</label><select id="mClient">'+clients.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')+'</select></div><div class="field"><label>Plan name</label><input id="mPlan" placeholder="e.g. General Pest Control"></div><div class="field"><label>Frequency rule</label><select id="mRule"><option>Daily</option><option>4 visits / month</option><option>6 total visits</option><option>1 visit / 3 months</option><option>Custom</option></select></div>'}else if(type==='job'){title.textContent='New Job Sheet';body.innerHTML='<div class="field"><label>Task / job</label><input id="mJobTitle" placeholder="e.g. Inspect hotel kitchen"></div><div class="field"><label>Client</label><select id="mJobClient"><option value="">Internal / office job</option>'+clients.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')+'</select></div><div class="field"><label>Due date</label><input id="mJobDate" type="date" value="'+iso(today)+'"></div><div class="field"><label>Assigned to</label><input id="mJobAssignee" value="Sandeep" placeholder="Employee name"></div><div class="field"><label>Priority</label><select id="mJobPriority"><option>Normal</option><option>High</option></select></div><div class="field"><label>Notes / instructions</label><textarea id="mJobNotes" placeholder="What exactly needs to be done?"></textarea></div>'}else if(type==='invoice'){title.textContent='New Invoice';body.innerHTML='<div class="field"><label>Client</label><select id="mClient">'+clients.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')+'</select></div><div class="field"><label>Invoice number</label><input id="mInvoiceNo" readonly value="Assigned automatically when synced"></div><div class="field"><label>Invoice date</label><input id="mInvoiceDate" type="date" value="'+iso(today)+'"></div><div class="field"><label>Service month</label><input id="mServiceMonth" type="month" value="'+iso(today).slice(0,7)+'"></div><div class="field"><label>Taxable amount</label><input id="mTaxable" type="number" min="0" value="0"></div><div class="field"><label>GST rate</label><select id="mGstRate"><option value="18">18%</option><option value="12">12%</option><option value="5">5%</option><option value="0">0%</option></select></div>'}else{title.textContent='WhatsApp Center';body.innerHTML='<div class="field"><label>What should Aahana receive?</label><select><option>Daily visit summary</option><option>Tomorrow reminders</option><option>Overdue alerts</option><option>All operational updates</option></select></div><div class="field"><label>Example update</label><textarea>Hotel Sunrise visit completed. Technician Raj. Treatment completed. Next visit tomorrow at 09:30.</textarea></div><div style="font-size:11px;color:var(--muted)">This prototype shows the workflow. Real WhatsApp sending/receiving requires a WhatsApp Business/Meta integration.</div>'}}
function closeModal(){document.getElementById('modal').classList.remove('open');const button=document.querySelector('.modal-foot .primary');button.textContent='Save';button.setAttribute('onclick','saveModal()')}
function saveModal(){if(modalType==='document')return;if(modalType==='payment'){savePaymentModal();return}if(modalType==='client'&&!document.getElementById('mName').value.trim()){alert('Enter a client name.');return}if(modalType==='visit'&&(!document.getElementById('mDate').value||!document.getElementById('mClient').value)){alert('Select a client and visit date.');return}if(modalType==='client'){let id=Math.max(0,...clients.map(c=>c.id))+1;clients.push({id,name:document.getElementById('mName').value||'New Client',site:document.getElementById('mSite').value||'New site',contact:document.getElementById('mContact').value||'—',plan:document.getElementById('mPlan').value||'Custom',rule:'Custom',visits:0,status:'Active'});alert('Client added.');}else if(modalType==='visit'){let id=Math.max(0,...visits.map(v=>v.id))+1,c=+document.getElementById('mClient').value;visits.push({id,client:c,date:document.getElementById('mDate').value,time:document.getElementById('mTime').value,plan:clients.find(x=>x.id===c)?.plan||'Service',status:'due',tech:document.getElementById('mTech').value||'Raj'});alert('Visit scheduled and added to the reminder queue.');}else if(modalType==='plan'){let c=+document.getElementById('mClient').value;plans.push({client:c,name:document.getElementById('mPlan').value||'New service plan',rule:document.getElementById('mRule').value,completed:0,total:document.getElementById('mRule').value.includes('6')?6:document.getElementById('mRule').value.includes('4')?4:1,next:iso(addDays(today,1))});alert('Service plan created.');}else if(modalType==='job'){const title=document.getElementById('mJobTitle').value.trim();if(!title){alert('Please enter the task / job.');return}const clientValue=document.getElementById('mJobClient').value;jobs.push({id:Math.max(0,...jobs.map(j=>j.id))+1,title,client:clientValue?+clientValue:null,due:document.getElementById('mJobDate').value||iso(today),assignee:document.getElementById('mJobAssignee').value.trim()||'Sandeep',priority:document.getElementById('mJobPriority').value, status:'open',notes:document.getElementById('mJobNotes').value.trim()});alert('Job added to the Job List.');renderJobs();}else if(modalType==='invoice'){const client=+document.getElementById('mClient').value,no='Draft pending sync',date=document.getElementById('mInvoiceDate').value||iso(today),taxable=Number(document.getElementById('mTaxable').value||0),rate=Number(document.getElementById('mGstRate').value||0);if(!client||!Number.isFinite(taxable)||taxable<=0){alert('Select a client and enter a taxable amount greater than zero.');return}if(!AahanaFinance.validDate(date)){alert('Enter a valid invoice date.');return}let invoiceAmounts;try{invoiceAmounts=AahanaFinance.invoiceAmounts(document.getElementById('mTaxable').value,rate)}catch(e){alert(e.message);return}const {gst,total}=invoiceAmounts;let billing={};try{billing=window.ERP?.billingFor(client,date,document.getElementById('mServiceMonth')?.value||date.slice(0,7),gst)||{}}catch(e){alert(e.message);return}invoices.push({id:Math.max(0,...invoices.map(i=>i.id))+1,no,client,date,taxable,gst,total,paid:0,billing,numberPending:true});alert('Invoice '+no+' created.');renderFinance();}closeModal();render()}
document.querySelector('.nav').insertAdjacentHTML('beforeend','<button data-section="jobs">Job List</button>');document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));document.getElementById(b.dataset.section).classList.add('active');}));
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function restoreSnapshot(d){clients=d.clients||[];visits=d.visits||[];visitReports=d.visitReports||[];plans=d.plans||[];jobs=d.jobs||[];invoices=d.invoices||[];payments=d.payments||[];expenses=d.expenses||[];ownerCapital=d.ownerCapital||[];accounts=d.accounts||[];vendors=d.vendors||[];vendorBills=d.vendorBills||[];vendorPayments=d.vendorPayments||[];erpRecords=d.erpRecords||[];historicalBills=d.historicalBills||[]}
function renderAll(){render();renderVisitReports();renderJobs();renderFinance();renderReports();renderExpenseRegister();setupVendorButton();renderVendorRegister();renderAccountRegister();window.ERP?.render();window.History?.render()}
const mutationNames=['saveModal','completeVisit','completeJob','recordPayment','addExpense','addCapital','addAccount','addVendor','addVendorBill','recordVendorPayment'];
mutationNames.forEach(name=>{const original=window[name];window[name]=function(...args){if(!cloudReady||cloudHydrating){alert('Wait for the cloud workspace to finish loading.');return}const before=JSON.stringify(localSnapshot());const result=original(...args);if(name==='completeVisit'&&before!==JSON.stringify(localSnapshot()))window.ERP?.afterVisit(args[0]);if(before!==JSON.stringify(localSnapshot())){renderAll();saveData()}return result}});
const sessionTools=document.createElement('div');sessionTools.className='sync-tools';sessionTools.innerHTML='<button class="btn" onclick="cloudSyncNow()">Retry sync</button><button class="btn" onclick="refreshCloudData(true)">Refresh</button><button class="btn" onclick="exportBackup()">Export backup</button><button class="btn" onclick="reloadCloudData()">Reload cloud</button><button class="btn" onclick="authSignOut()">Sign out</button>';document.querySelector('.header').insertAdjacentElement('afterend',sessionTools);
window.addEventListener('beforeunload',event=>{persistCache();if(cloudDirty){event.preventDefault();event.returnValue=''}});
if(!supabaseClient)authStatus('Sign-in library could not load. Check your connection and reload.',true);

window.addEventListener('focus',()=>refreshCloudData());window.addEventListener('online',()=>cloudDirty?cloudSyncNow():refreshCloudData(true));setInterval(()=>{if(document.visibilityState==='visible')refreshCloudData()},60000);
